INSERT INTO submissions (id, round_id, song_id, submitter_id, comment, created_at, vote_total) VALUES (234, 25, 230, 2, 'Adam Schlesinger is the Andy Warhol of pop music. He is a master at crafting songs that manage to be ironic and earnest at the same time, simple and straightforward yet beautiful in their straightforwardness. It’s no wonder that when Tom Hanks wanted to make a movie about the very concept of the one hit wonder, he got Adam Schlesinger to write the fictional “one hit” in question. (That Thing You Do!, for those keeping score at home.) Stacy’s Mom is unassailable for its lyrical creativity and pop ingenuity, but look even a little bit below the surface and you’ll find a career filled with clever, insightful, delightfully sugary pop goodness. Trust me, this Fountain is deep. ', '2025-07-03T12:15:34Z', 2);
INSERT INTO submissions (id, round_id, song_id, submitter_id, comment, created_at, vote_total) VALUES (235, 25, 231, 11, NULL, '2025-07-03T06:40:15Z', 2);
