INSERT INTO submissions (id, round_id, song_id, submitter_id, comment, created_at, vote_total) VALUES (247, 26, 243, 3, 'I’m prepared to be buried in downvotes, but this is one of the most formative recordings of my musical journey. This very performance opened my eyes to the value of screaming, as it’s used very intentionally to convey the emotion of the song. Haunting performance by one of the all time greats. ', '2025-07-06T14:53:08Z', -1);
