INSERT INTO submissions (id, round_id, song_id, submitter_id, comment, created_at, vote_total) VALUES (268, 28, 264, 4, 'Trying to pull a Sammy on you all here. I remember hearing this song when I was about four years old and absolutely loving it. Then for the next 12 years I could distinctly remember the best and the 1-2-3 counting but assumed the song was lost forever. Then one random day, I heard about half a second of the counting part as my mom was flipping through the radio and freaked out and made her flip back through until we found it. And since then it’s been an all-time favorite. One thing I think this reveals is that time and place play a huge role in the music I like, which makes it hard to guess. ', '2025-07-24T12:56:52Z', 1);
