INSERT INTO submissions (id, round_id, song_id, submitter_id, comment, created_at, vote_total) VALUES (337, 34, 333, 3, 'The last week of senior year, your high school sweetheart broke up with you. Heartbroken, you set out with your best friend from your childhood home in the suburbs of LA on a summer-long roadtrip to nowhere in particular in the family wagon. As the dying sun sets the canyon walls ablaze and you settle in for a long night on the road, this song comes on on the radio. ', '2025-09-03T22:53:20Z', 4);
