INSERT INTO submissions (id, round_id, song_id, submitter_id, comment, created_at, vote_total) VALUES (772, 68, 760, 2, 'The Magic Whip is my personal favorite pick for a great late career entry in a band’s lifetime. Blur hadn’t put out an album since 2003 (hadn’t put out a good one since 1998), had broken up for several years prior to the tour that preceded this album, and never had any intentions of actually producing this one. They were set to play at a music festival in Japan that got mysteriously cancelled and the band were stranded for days in Hong Kong; they made this album on a lark while stranded, and it ended up being a surprise late career masterpiece.', '2026-05-19T04:14:31Z', 1);
INSERT INTO submissions (id, round_id, song_id, submitter_id, comment, created_at, vote_total) VALUES (773, 68, 761, 10, NULL, '2026-05-20T03:09:48Z', -5);
